files.content:
.root {
  --vt-surface: #F7F9FC;
  --vt-surface-2: #FFFFFF;
  --vt-surface-deep: #0F172A;
  --vt-ink: #0F172A;
  --vt-ink-soft: #64748B;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #0047AB;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #0047AB;
  --vt-accent-on-deep: #8AB4F8;
  --vt-line: #E2E8F0;
  --vt-surface-rgb: 247, 249, 252;
  --vt-surface-deep-rgb: 15, 23, 42;
  --vt-on-deep-rgb: 255, 255, 255;
  --vt-serif: 'Fraunces', Georgia, serif;
  --vt-sans: 'Inter', system-ui, sans-serif;
  --vt-gutter: clamp(1.5rem, 4vw, 4rem);
  --vt-space-sm: clamp(1rem, 2vw, 2rem);
  --vt-space-md: clamp(2rem, 5vw, 5rem);
  --vt-space-lg: clamp(4rem, 10vh, 10rem);
  --vt-space-xl: clamp(6rem, 15vh, 15rem);
  font-family: var(--vt-sans);
  font-weight: 400;
  line-height: 1.7;
  color: var(--vt-ink);
  background: var(--vt-surface);
  -webkit-font-smoothing: antialiased;
}

.root :where(p, ul, ol, h1, h2, h3, h4, figure, blockquote) { margin: 0; }
.root :where(a) { color: inherit; text-decoration: none; }
.root :where(button) { font: inherit; }
.root :where(img) { display: block; width: 100%; height: 100%; object-fit: cover; }
.root a:focus-visible { outline: 2px solid var(--vt-accent); outline-offset: 2px; }

.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 1.5rem var(--vt-gutter);
  background: var(--vt-surface-deep);
  border-bottom: 1px solid rgba(var(--vt-on-deep-rgb), 0.08);
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1400px;
  margin: 0 auto;
}

.logo {
  display: inline-flex;
  align-items: center;
  font-family: var(--vt-serif);
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -0.02em;
  color: var(--vt-on-deep);
  text-transform: uppercase;
}

.navLinks {
  display: flex;
  gap: 2rem;
}

.navLinks a {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(var(--vt-on-deep-rgb), 0.65);
  transition: color 0.3s ease, letter-spacing 0.3s ease;
}

.navLinks a:hover {
  color: var(--vt-on-deep);
  letter-spacing: 0.14em;
}

.hero {
  position: relative;
  min-height: 100vh;
  width: 100%;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
}

.heroImage {
  position: absolute;
  inset: 0;
}

.heroImage::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(var(--vt-surface-deep-rgb), 0.65) 0%, rgba(var(--vt-surface-deep-rgb), 0.15) 40%, rgba(var(--vt-surface-deep-rgb), 0.05) 100%);
}

.heroContent {
  position: relative;
  z-index: 1;
  width: 100%;
  padding: clamp(3rem, 8vh, 8rem) var(--vt-gutter);
  color: var(--vt-on-deep);
}

.heroIssue {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  margin-bottom: 1.5rem;
  opacity: 0.8;
}

.heroTitle {
  font-family: var(--vt-serif);
  font-size: clamp(3rem, 8vw, 7.5rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.03em;
  max-width: 14ch;
  margin-bottom: 2rem;
}

.heroTitle em {
  font-style: italic;
  font-weight: 400;
}

.heroMeta {
  display: flex;
  align-items: center;
  gap: 2rem;
  font-size: 0.8rem;
  letter-spacing: 0.04em;
  opacity: 0.7;
}

.heroMeta span {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.divider {
  width: 40px;
  height: 1px;
  background: var(--vt-on-deep);
  opacity: 0.4;
}

.heroScroll {
  position: absolute;
  bottom: clamp(3rem, 8vh, 8rem);
  right: var(--vt-gutter);
  writing-mode: vertical-rl;
  font-size: 0.65rem;
  font-weight: 500;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--vt-on-deep);
  opacity: 0.6;
  display: flex;
  align-items: center;
  gap: 1rem;
}

.heroScroll::before {
  content: '';
  width: 1px;
  height: 60px;
  background: var(--vt-on-deep);
  opacity: 0.4;
}

.prologue {
  padding: var(--vt-space-xl) var(--vt-gutter);
  background: var(--vt-surface-2);
}

.prologueInner {
  max-width: 60ch;
  margin: 0 auto;
}

.prologueLabel {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: var(--vt-space-md);
  display: flex;
  align-items: center;
  gap: 1rem;
}

.prologueLabel::after {
  content: '';
  flex: 1;
  max-width: 120px;
  height: 1px;
  background: var(--vt-accent);
  opacity: 0.3;
}

.prologueText {
  font-family: var(--vt-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.625rem);
  line-height: 1.75;
  color: var(--vt-ink);
  letter-spacing: -0.01em;
  margin-bottom: 1.5em;
}

.prologueFirst::first-letter {
  font-family: var(--vt-serif);
  font-weight: 700;
  float: left;
  font-size: 5.5em;
  line-height: 0.8;
  margin-right: 0.08em;
  margin-top: 0.05em;
  color: var(--vt-accent);
}

.pullquote {
  margin: var(--vt-space-md) 0;
  padding: var(--vt-space-sm) 0;
  border-top: 1px solid var(--vt-line);
  border-bottom: 1px solid var(--vt-line);
}

.pullquote p {
  font-family: var(--vt-serif);
  font-style: italic;
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  line-height: 1.45;
  color: var(--vt-accent);
  letter-spacing: -0.02em;
}

.pullquote cite {
  display: block;
  margin-top: 1rem;
  font-family: var(--vt-sans);
  font-style: normal;
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--vt-ink-soft);
}

.route {
  position: relative;
  background: var(--vt-surface);
}

.routeBg {
  position: sticky;
  top: 0;
  height: 100vh;
  width: 100%;
  overflow: hidden;
}

.routeBg img {
  position: absolute;
  inset: 0;
}

.routeBg::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, var(--vt-surface) 0%, var(--vt-surface) 15%, rgba(var(--vt-surface-rgb), 0.85) 30%, rgba(var(--vt-surface-rgb), 0.45) 50%, rgba(var(--vt-surface-rgb), 0.1) 75%, transparent 100%);
  z-index: 1;
  pointer-events: none;
}

.routeChapters {
  position: relative;
  z-index: 2;
  margin-top: -100vh;
  padding: var(--vt-space-xl) var(--vt-gutter);
}

.chapter {
  max-width: 52ch;
  min-height: 80vh;
  padding: 10vh 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.chapter:first-child {
  padding-top: 5vh;
}

.chapterNumber {
  font-family: var(--vt-serif);
  font-size: clamp(4rem, 8vw, 6rem);
  font-weight: 400;
  color: var(--vt-accent);
  opacity: 0.12;
  line-height: 1;
  margin-bottom: 1rem;
}

.chapterLocation {
  font-size: 0.7rem;
  font-weight: 500;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 1rem;
}

.chapterTitle {
  font-family: var(--vt-serif);
  font-size: clamp(2rem, 4vw, 3.25rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--vt-ink);
  margin-bottom: 1.5rem;
  max-width: 18ch;
}

.chapterBody {
  font-size: 0.95rem;
  line-height: 1.8;
  color: var(--vt-ink-soft);
  max-width: 48ch;
}

.chapterBody + .chapterBody {
  margin-top: 1em;
}

.chapterLink {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  margin-top: 2rem;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--vt-accent);
}

.chapterLink svg {
  width: 16px;
  height: 16px;
  transition: transform 0.3s ease;
}

.chapterLink:hover svg {
  transform: translateX(4px);
}

.gallery {
  padding: var(--vt-space-xl) var(--vt-gutter);
  background: var(--vt-surface-2);
}

.galleryHeader {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: var(--vt-space-md);
  padding-bottom: var(--vt-space-sm);
  border-bottom: 1px solid var(--vt-line);
}

.galleryTitle {
  font-family: var(--vt-serif);
  font-size: clamp(2.5rem, 5vw, 4rem);
  font-weight: 400;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.galleryCount {
  font-size: 0.75rem;
  font-weight: 500;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--vt-ink-soft);
  padding-bottom: 0.5rem;
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-auto-rows: clamp(180px, 20vw, 280px);
  gap: 6px;
}

.galleryItem {
  position: relative;
  overflow: hidden;
}

.galleryItem::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(var(--vt-surface-deep-rgb), 0.5) 0%, transparent 50%);
  opacity: 0;
  transition: opacity 0.4s ease;
}

.galleryItem:hover::after {
  opacity: 1;
}

.galleryItem img {
  transition: transform 0.6s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.galleryItem:hover img {
  transform: scale(1.04);
}

.galleryCaption {
  position: absolute;
  bottom: 1rem;
  left: 1rem;
  right: 1rem;
  z-index: 2;
  color: var(--vt-on-deep);
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 0.4s ease 0.05s, transform 0.4s ease 0.05s;
}

.galleryItem:hover .galleryCaption {
  opacity: 1;
  transform: translateY(0);
}

.galleryCaptionTitle {
  font-family: var(--vt-serif);
  font-size: 1rem;
  font-weight: 500;
  margin-bottom: 0.2rem;
}

.galleryCaptionSub {
  font-size: 0.7rem;
  font-weight: 400;
  letter-spacing: 0.04em;
  opacity: 0.7;
}

.tall {
  grid-row: span 2;
}

.footer {
  padding: var(--vt-space-xl) var(--vt-gutter) var(--vt-space-md);
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
}

.footerTop {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: var(--vt-gutter);
  padding-bottom: var(--vt-space-lg);
  border-bottom: 1px solid rgba(var(--vt-on-deep-rgb), 0.1);
}

.footerBrandTitle {
  font-family: var(--vt-serif);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.02em;
  margin-bottom: 1.5rem;
}

.footerBrandDesc,
.footerCtaText {
  font-size: 0.85rem;
  line-height: 1.7;
  color: rgba(var(--vt-on-deep-rgb), 0.5);
  max-width: 32ch;
}

.footerColTitle {
  font-size: 0.65rem;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(var(--vt-on-deep-rgb), 0.35);
  margin-bottom: 1.5rem;
}

.footerCol a {
  color: rgba(var(--vt-on-deep-rgb), 0.7);
  transition: color 0.3s ease;
}

.footerCol a:hover {
  color: var(--vt-on-deep);
  opacity: 1;
}

.socialLinks {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.footerBottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--vt-space-md);
}

.footerCopy,
.footerInfo {
  font-size: 0.75rem;
  color: rgba(var(--vt-on-deep-rgb), 0.3);
}

@media (max-width: 1024px) {
  .routeChapters {
    padding: var(--vt-space-md) var(--vt-gutter);
  }

  .chapter {
    min-height: auto;
    padding: 6vh 0;
  }

  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footerTop {
    grid-template-columns: 1fr 1fr;
    row-gap: var(--vt-space-md);
  }
}

@media (max-width: 680px) {
  .nav {
    padding: 1rem var(--vt-gutter);
  }

  .navIn {
    flex-wrap: wrap;
    gap: 0.75rem;
  }

  .navLinks {
    width: 100%;
    justify-content: space-between;
    gap: 0.75rem;
  }

  .navLinks a {
    font-size: 0.65rem;
  }

  .heroTitle {
    font-size: clamp(2.5rem, 12vw, 4.5rem);
  }

  .heroScroll {
    display: none;
  }

  .heroMeta {
    flex-wrap: wrap;
    gap: 1rem;
  }

  .prologueFirst::first-letter {
    font-size: 4em;
  }

  .chapterNumber {
    font-size: 3.5rem;
  }

  .galleryGrid {
    grid-template-columns: 1fr 1fr;
    grid-auto-rows: clamp(140px, 30vw, 200px);
  }

  .footerTop {
    grid-template-columns: 1fr;
  }

  .footerBottom {
    flex-direction: column;
    gap: 1.5rem;
    text-align: center;
  }
}

@media (prefers-reduced-motion: reduce) {
  .root a,
  .root img,
  .root .galleryItem,
  .root .galleryCaption,
  .root .navLinks a {
    transition: none;
  }

  .root .heroScroll::before {
    animation: none;
  }
}
